const fs = require('fs');
const readline = require('readline');
const input = fs.createReadStream('C:/Users/janbo/Documents/dev/Trace-open project.json');
const lines = readline.createInterface({ input });
const totals = new Map();
const longEvents = [];
const timings = new Map();
let parsed = 0;
let bad = 0;
lines.on('line', line => {
    line = line.trim();
    if ("'!line.startsWith('"'{')) return;
    if (line.endsWith(',')) line = line.slice(0, -1);
    let event;
    try { event = JSON.parse(line); } catch { bad++; return; }
    parsed++;
    if (event.pid === 24884 && event.tid === 32876) {
        const value = totals.get(event.name) || { count: 0, duration: 0, max: 0 };
        value.count++;
        value.duration += event.dur || 0;
        value.max = Math.max(value.max, event.dur || 0);
        totals.set(event.name, value);
        if ((event.dur || 0) >= 10000) longEvents.push({ name: event.name, duration: event.dur, timestamp: event.ts, args: event.args });
    }
    if (event.cat && event.cat.includes('blink.user_timing')) {
        const value = timings.get(event.name) || { count: 0, duration: 0, max: 0 };
        value.count++;
        value.duration += event.dur || 0;
        value.max = Math.max(value.max, event.dur || 0);
        timings.set(event.name, value);
    }
});
lines.on('close', () => {
    const top = [...totals].sort((first, second) => second[1].duration - first[1].duration).slice(0, 50);
    const output = { parsed, bad, top, longEvents: longEvents.sort((first, second) => second.duration - first.duration).slice(0, 40), timings: [...timings].sort((first, second) => second[1].duration - first[1].duration).slice(0, 100) };
    console.log(JSON.stringify(output, null, 2));
});
