import { useSyncExternalStore } from 'react'
import { dataService, type DataService, type DataServiceState } from '../../services/data/data_service'

const snapshots = new WeakMap<DataService, DataServiceState>()

function isSameDataServiceState(first: DataServiceState, second: DataServiceState) {
    return first.project === second.project
        && first.runningAgents === second.runningAgents
        && first.snapshot === second.snapshot
}

function getProjectStateSnapshot(service: DataService): DataServiceState {
    const nextSnapshot = service.getState()
    const currentSnapshot = snapshots.get(service)
    if (currentSnapshot && isSameDataServiceState(currentSnapshot, nextSnapshot)) return currentSnapshot

    snapshots.set(service, nextSnapshot)

    return nextSnapshot
}

export function useProjectState(service: DataService = dataService): DataServiceState {
    return useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener('changed', onStoreChange)

            return () => service.removeEventListener('changed', onStoreChange)
        },
        () => getProjectStateSnapshot(service),
        () => getProjectStateSnapshot(service),
    )
}

import { AppBar, Box, Toolbar } from '@mui/material'
import type { ReactNode } from 'react'
import { DRAG_REGION, NO_DRAG_REGION } from '../drag_region'
import { ThemeToggleButton } from '../theme_toggle_button'
import { isElectron } from '../../../services/electron_lifecycle_bridge'
import { ProjectNameLabel } from './project_name_label'
import { MobileMenuButton } from './mobile_menu_button'

const MENU_ROW_HEIGHT = 44
const SEARCH_WIDTH = 286
const PROJECT_NAME_MAX_WIDTH = 240
const APPLICATION_ICON_SOURCE = `${import.meta.env.BASE_URL}favicon.svg`

interface MainToolbarProps {
    isMobile: boolean
    mobileAction: ReactNode
    onOpenMenu: () => void
    panel: ReactNode
    search: ReactNode
    tabs: ReactNode
}

/**
 * Top application toolbar; hosts menu tabs, search, and the desktop drag region.
 * Interactive controls opt out of dragging so the remaining row space can move the window.
 */
export function MainToolbar(props: MainToolbarProps) {
    const { isMobile, mobileAction, onOpenMenu, panel, search, tabs } = props

    return (
        <AppBar
            color="default"
            elevation={0}
            position="static"
            sx={{ borderBottom: 1, borderColor: 'divider', bgcolor: 'background.paper' }}
        >
            <Toolbar
                disableGutters
                style={DRAG_REGION}
                sx={{ gap: 0.5, height: MENU_ROW_HEIGHT, minHeight: `${MENU_ROW_HEIGHT}px !important`, px: 1.5 }}
                variant="dense"
            >
                {isMobile ? (
                    <MobileMenuButton onOpenMenu={onOpenMenu} />
                ) : null}
                <Box sx={{ alignItems: 'center', display: 'flex', flexShrink: 0 }}>
                    <Box
                        alt="MDÂ² application icon"
                        component="img"
                        src={APPLICATION_ICON_SOURCE}
                        sx={{
                            height: 24,
                            width: 24,
                        }}
                    />
                </Box>
                <Box style={NO_DRAG_REGION} sx={{ alignSelf: 'stretch', display: 'flex', flexShrink: 0 }}>
                    {tabs}
                </Box>
                {!isMobile ? (
                    <Box
                        data-testid="project-name-region"
                        sx={{ alignItems: 'center', display: 'flex', flex: 1, justifyContent: 'center', minWidth: 16, overflow: 'hidden' }}
                    >
                        <Box sx={{ maxWidth: PROJECT_NAME_MAX_WIDTH, minWidth: 0 }}>
                            <ProjectNameLabel />
                        </Box>
                    </Box>
                ) : null}
                {isMobile ? (
                    <Box style={NO_DRAG_REGION}>
                        {mobileAction}
                    </Box>
                ) : null}
                {isMobile ? (
                    <Box style={NO_DRAG_REGION}>
                        {search}
                    </Box>
                ) : (
                    <Box style={NO_DRAG_REGION}>
                        <ThemeToggleButton />
                    </Box>
                )}
                {!isMobile ? (
                    <Box
                        style={NO_DRAG_REGION}
                        sx={{ display: 'flex', flex: `0 0 ${SEARCH_WIDTH}px`, ml: 0.5, minWidth: 180, mr: isElectron() ? '130px' : 0 }}
                    >
                        {search}
                    </Box>
                ) : null}
            </Toolbar>
            <Box style={NO_DRAG_REGION}>
                {panel}
            </Box>
        </AppBar>
    )
}

import { Box, useMediaQuery, useTheme } from '@mui/material'
import { useCallback, useEffect, useMemo, useState, type ReactNode } from 'react'
import { navigateTo, useAppLocation } from '../../app/app_navigation'
import type { UseGithubAuthResult } from '../../auth/use_github_auth'
import { ConfigPage } from '../config/config_page'
import { useProjectReference } from '../hooks/use_project_reference'
import { ProjectWorkspace } from '../project_workspace'
import { createSearchRegexpAgent, isSearchRegexpAgentAvailable } from '../../services/search/search_regexp_agent'
import { GLOBAL_SEARCH_SHORTCUT_BINDING } from '../../services/search/search_open_service'
import { keyboardShortcutService } from '../../services/shortcuts/keyboard_shortcut_service'
import { AppMenu } from './menu/app_menu'
import { SearchControl } from './search/search_control'
import { StatusBar } from './status_bar'
import type { ProjectOpenResolution } from '../../services/project/project_session_service'

interface MainWindowProps {
    auth: UseGithubAuthResult
    initialProjectOpenResolution: ProjectOpenResolution | null
    toolbarAction: ReactNode
}

/** Main window: owns the global layout and switches between desktop and mobile presentations. */
export function MainWindow(props: MainWindowProps) {
    const { auth, initialProjectOpenResolution, toolbarAction } = props
    const location = useAppLocation()
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const [isMenuOpen, setIsMenuOpen] = useState(false)
    const project = useProjectReference()
    const isConfigOpen = location.pathname === '/config'
    const regexpAgent = useMemo(
        () => isSearchRegexpAgentAvailable() ? createSearchRegexpAgent() : undefined,
        [],
    )

    useEffect(() => keyboardShortcutService.register(GLOBAL_SEARCH_SHORTCUT_BINDING), [])

    const handleOpenMenu = useCallback(() => {
        setIsMenuOpen(true)
    }, [])

    const handleCloseMenu = useCallback(() => {
        setIsMenuOpen(false)
    }, [])

    const handleOpenConfig = useCallback(() => {
        navigateTo('/config')
    }, [])

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
            <AppMenu
                accessToken={auth.accessToken}
                auth={auth}
                extraActions={toolbarAction}
                initialProjectOpenResolution={initialProjectOpenResolution}
                isGithubAuthenticated={auth.isAuthenticated}
                isMobile={isMobile}
                onOpenConfig={handleOpenConfig}
                onOpenMobileMenu={handleOpenMenu}
                search={<SearchControl isMobile={isMobile} regexpAgent={regexpAgent} />}
            />
            <ProjectWorkspace
                auth={auth}
                isMenuOpen={isMenuOpen}
                key={project ? `${project.id}:${project.branch}` : 'no-project'}
                onLeftPanelInteraction={handleCloseMenu}
            />
            {!isMobile ? <StatusBar /> : null}
            {isConfigOpen ? <ConfigPage hash={location.hash} /> : null}
        </Box>
    )
}

