/** Stable metadata-only projection. Body and activity changes cannot update it. */
export function useCardMetadata(path: string | null, service: DataService = dataService) {
    const cardRef = useRef<CardMetadataSnapshot | null>(null)
    const select = useCallback((card: Card | null) => {
        if (card && cardRef.current && sameCardMetadata(cardRef.current, card)) return cardRef.current
        cardRef.current = card ? cardMetadataSnapshot(card) : null

        return cardRef.current
    }, [])
    const subscribe = useCallback((onStoreChange: () => void) => {
        const handleLifecycle = (event: Event) => {
            if (eventMatchesPath(event, path)) onStoreChange()
        }
        const fieldEvents = path ? CARD_METADATA_FIELDS.map((field) => cardFieldChangedEvent(path, field)) : []
        fieldEvents.forEach((eventName) => service.addEventListener(eventName, onStoreChange))
        service.addEventListener(CARD_ADDED_EVENT, handleLifecycle)
        service.addEventListener(CARD_REMOVED_EVENT, handleLifecycle)

        return () => {
            fieldEvents.forEach((eventName) => service.removeEventListener(eventName, onStoreChange))
            service.removeEventListener(CARD_ADDED_EVENT, handleLifecycle)
            service.removeEventListener(CARD_REMOVED_EVENT, handleLifecycle)
        }
    }, [path, service])
    const getSnapshot = useCallback(() => select(findCard(path, service)), [path, select, service])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/** Reads metadata for one stable card identity, including its current path. */
export function useCardMetadataByInternalId(internalId: string | null, service: DataService = dataService) {
    const cardRef = useRef<CardMetadataSnapshot | null>(null)
    const select = useCallback((card: Card | null) => {
        if (card && cardRef.current && sameCardMetadata(cardRef.current, card)) return cardRef.current
        cardRef.current = card ? cardMetadataSnapshot(card) : null

        return cardRef.current
    }, [])
    const subscribe = useCallback((onStoreChange: () => void) => {
        const handleLifecycle = (event: Event) => {
            if (eventMatchesInternalId(event, internalId)) onStoreChange()
        }
        const fieldEvents = CARD_METADATA_FIELDS.map((field) => cardCollectionFieldChangedEvent(field))
        fieldEvents.forEach((eventName) => service.addEventListener(eventName, onStoreChange))
        service.addEventListener(CARD_ADDED_EVENT, handleLifecycle)
        service.addEventListener(CARD_REMOVED_EVENT, handleLifecycle)

        return () => {
            fieldEvents.forEach((eventName) => service.removeEventListener(eventName, onStoreChange))
            service.removeEventListener(CARD_ADDED_EVENT, handleLifecycle)
            service.removeEventListener(CARD_REMOVED_EVENT, handleLifecycle)
        }
    }, [internalId, service])
    const getSnapshot = useCallback(() => select(findCardByInternalId(internalId, service)), [internalId, select, service])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/** Stable affects-only projection for affects editor. */
export function useCardAffects(path: string | null, service: DataService = dataService) {
    const snapshotRef = useRef<CardAffectsSnapshot | null>(null)
    const select = useCallback((card: Card | null) => {
        if (!card) return null
        const previous = snapshotRef.current
        const unchanged = previous
            && previous.affects === card.header.affects
            && previous.id === card.header.id
            && previous.path === card.path
        if (unchanged) return previous

        const next = { affects: card.header.affects, id: card.header.id, path: card.path }
        snapshotRef.current = next

        return next
    }, [])

    return useCardField(path, 'affects', select, service)
}

import { slugifyTitle } from '../../data/card_naming'
import type { CardSeparator } from '../../data/card_identifiers'
import { getElectronActionBridge, type WorktreeDiffResult } from '../../data/electron_action_bridge'
import type {
    Card,
    ProjectReference,
    ProjectSnapshot,
    StorageService,
    WorktreeRecord,
    WorktreeRemovalMode,
    WorktreeState,
    WorktreeStatus,
} from '../../data/data_types'
import { register } from '../service_injector'
import { PrimaryWorktreeSelectionError } from './worktree_errors'

interface WorktreeServiceDependencies {
    assignCardWorktree: (path: string, worktree: number, branch: string) => void
    cardSeparatorProvider: () => CardSeparator
    clearCardBranch: (path: string) => void
    flushPendingChanges: () => Promise<void>
    projectFolderProvider: () => string
    projectProvider: () => ProjectReference | null
    snapshotProvider: () => ProjectSnapshot | null
    storageProvider: () => StorageService | null
    unassignCardWorktree: (path: string) => void
}

/** A staged removal keeps the folder disposition chosen in the confirmation dialog until Save applies it. */
export interface WorktreeDraftRemoval {
    mode: WorktreeRemovalMode
    path: string
}

export interface WorktreeDraft {
    additions: string[]
    applying: boolean
    records: WorktreeRecord[]
    removals: WorktreeDraftRemoval[]
    selecting: boolean
}

function worktreePathKey(folderPath: string) {
    return folderPath.replace(/\\/gu, '/').replace(/\/+$/u, '').toLowerCase()
}

/** Same outgoing-status condition used by worktree integration and diff controls. */
export function isWorktreeIntegratable(record: WorktreeRecord | null | undefined) {
    return !!record?.valid && (record.status.dirty || record.status.baseAhead > 0)
}

export class WorktreeService extends EventTarget {
    private assignCardWorktreeValue: ((path: string, worktree: number, branch: string) => void) | null = null
    private cardSeparatorProvider: (() => CardSeparator) | null = null
